/* Referência imutável da versão BUILD 1.3.1, antes da extração de loot/recompensas. */
function collect(i){const p=G.hero;switch(i.kind){case 'coins':p.coins+=i.value;G.treasure+=i.value;log(`Você encontra ${i.value} lascas de âmbar ósseo.`, '◈');break;case 'potion':p.potions++;log('Um frasco de seiva curativa sobreviveu à ruína.','✚');break;case 'mana':p.mana=clamp(p.mana+6,0,p.maxmana);log('Um cristal restitui 6 pontos de foco.','✧');break;case 'heal':p.hp=clamp(p.hp+9,0,p.maxhp);log('Ossos quentes devolvem 9 pontos de vida.','♥');break;case 'trap':{let damage=rand(3,7)+G.floor;receiveDamage(damage,'Uma inscrição explode sob seus pés!');break;}case 'relic':{if(window.GolzdovRelicOffers.available(RELICS,p).length){G.pendingRelicOffer={source:'relicario',offers:null};log('Um relicário revela duas inscrições. Você escolherá uma delas.','✥');}else{p.coins+=12;log('Um relicário vazio guarda 12 lascas.','◈');}break;}case 'weapon':{let up=rand(1,2);p.atk+=up;p.weapon=pick(['Lâmina das Costelas','Arco de Osso','Martelo Fendido','Bastão da Sombra','Presa Polida']);log(`Arma: ${p.weapon}. Ataque +${up}!`,'⚔');break;}case 'armor':{p.def++;p.armor=pick(['Placas Ancestrais','Colete de Ferro Negro','Cota de Vértebras','Manto de Osso']);log(`${p.armor}: defesa +1!`,'◆');break;}}beep(i.kind==='trap'?115:590,.11);}
function killEnemy(e,source='effect'){const d=ENEMIES[e.type];G.kills++;G.hero.xp+=d.xp;G.hero.coins+=d.gold;G.treasure+=d.gold;G.hero.mana=clamp(G.hero.mana+1,0,G.hero.maxmana);G.enemies=G.enemies.filter(x=>x!==e);relicEvent('onKill',{enemy:e,kind:source});log(`${d.name} cai. +${d.xp} experiência, +${d.gold} âmbar.`,'✥');if(e.type==='boss'){G.bossDown=true;}}
